import{_ as d,o as a,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"সাধনা স্তরের ঐক্যকৃত বিভাজন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/14-修炼境界统一划分.md","filePath":"bn/14-修炼境界统一划分.md"}'),o={name:"bn/14-修炼境界统一划分.md"};function r(e,t,u,h,q,n){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="সাধনা-স্তরের-ঐক্যকৃত-বিভাজন" tabindex="-1">সাধনা স্তরের ঐক্যকৃত বিভাজন <a class="header-anchor" href="#সাধনা-স্তরের-ঐক্যকৃত-বিভাজন" aria-label="Permalink to &quot;সাধনা স্তরের ঐক্যকৃত বিভাজন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>14</td></tr><tr><td>মডিউল</td><td>মহাবিশ্বের আইন এবং সাধনা পদ্ধতি</td></tr><tr><td>মূল কীওয়ার্ড</td><td>স্তর বিভাজন, ঐক্যকৃত মানদণ্ড, নয়টি স্তর, ক্রস-সিস্টেম তুলনা, অ্যাঙ্কর সার্টিফিকেশন</td></tr></tbody></table><h2 id="i-ঐক্যকৃত-স্তর-বিভাজনের-প্রয়োজনীয়তা" tabindex="-1">I. ঐক্যকৃত স্তর বিভাজনের প্রয়োজনীয়তা <a class="header-anchor" href="#i-ঐক্যকৃত-স্তর-বিভাজনের-প্রয়োজনীয়তা" aria-label="Permalink to &quot;I. ঐক্যকৃত স্তর বিভাজনের প্রয়োজনীয়তা&quot;">​</a></h2><p>অ্যাঙ্কর সিম্বায়োটিক সিভিলাইজেশন প্রতিষ্ঠার আগে, হেঙ্গ-ইউয়ান জুতে হাজার হাজার সাধনা পদ্ধতি বিদ্যমান ছিল, এবং প্রতিটি সিস্টেমের নিজস্ব স্বাধীন স্তর বিভাজনের মানদণ্ড ছিল। এই বিশৃঙ্খল স্তর ব্যবস্থার ফলে একসিরিজ সমস্যা দেখা দিয়েছিল: বিভিন্ন সিস্টেমের সাধকদের মধ্যে শক্তির তুলনা করা কঠিন ছিল, ক্রস-সিস্টেম যোগাযোগ এবং সহযোগিতায় সাধারণ ভাষার অভাব ছিল, সম্পদ বণ্টন এবং সামাজিক মর্যাদা মূল্যায়নে ঐক্যকৃত ভিত্তির অভাব ছিল, এমনকি &quot;একই স্তর কিন্তু ভিন্ন শক্তি&quot;র মারাত্মক অবিচারের ঘটনাও দেখা দিয়েছিল।</p><p>অ্যাঙ্কর সিম্বায়োটিক সিভিলাইজেশন প্রতিষ্ঠার পর, এই সমস্যা সমাধানের জন্য, ওয়ান-জু রিপাবলিকান কাউন্সিলের অধীনস্থ &quot;সাধনা মানদণ্ড কমিটি&quot; নেতৃত্বে তিনশট সিস্টেমের প্রতিনিধি সাধকদের সাথে মিলে, দীর্ঘকালীন গবেষণা এবং যুক্তির পর, এই &quot;সাধনা স্তরের ঐক্যকৃত বিভাজন মানদণ্ড&quot; প্রণয়ন করা হয়েছে। এই মানদণ্ডটি কোনো একক সিস্টেমের স্তরের নামের উপর ভিত্তি করে নয়, বরং সাধকের মহাবিশ্বের মূল আইনের বোঝার গভীরতা, শক্তি নিয়ন্ত্রণের নির্ভুলতা, চেতনার বিবর্তনের মাত্রা, এবং সিম্বায়োটিক নেটওয়ার্কে অবদানের মাত্রা — এই চারটি মাত্রাকে মূল সূচক হিসেবে নিয়ে একটি ক্রস-সিস্টেম সার্বজনীন স্তর বিভাজন ব্যবস্থা তৈরি করেছে।</p><p>ঐক্যকৃত স্তর বিভাজনের মূল নীতি হলো &quot;নামের চেয়ে সত্তাকে গুরুত্ব দেওয়া&quot;: সাধক যে সিস্টেম ব্যবহার করুক না কেন, স্তরের নাম যাই হোক, যতক্ষণ না তার সত্তা ঐক্যকৃত মানদণ্ডের সংশ্লিষ্ট স্তরে পৌঁছায়, তাকে সেই স্তর হিসেবে চিহ্নিত করা হয়। এই নীতিটি স্তর মূল্যায়নের ন্যায়বিচার এবং বস্তুনিষ্ঠতা নিশ্চিত করে।</p><h2 id="ii-নয়টি-স্তরের-সারসংক্ষেপ" tabindex="-1">II. নয়টি স্তরের সারসংক্ষেপ <a class="header-anchor" href="#ii-নয়টি-স্তরের-সারসংক্ষেপ" aria-label="Permalink to &quot;II. নয়টি স্তরের সারসংক্ষেপ&quot;">​</a></h2><p>ঐক্যকৃত স্তর বিভাজন মানদণ্ড সাধকের বিবর্তনের যাত্রাকে নয়টি স্তরে বিভক্ত করেছে, নিম্ন থেকে উচ্চ ক্রমানুসারে:</p><table tabindex="0"><thead><tr><th>স্তর ক্রম</th><th>স্তরের নাম</th><th>মূল বৈশিষ্ট্য</th><th>মূল তিন ভিত্তির স্তরের সাথে মোটামুটি মিল</th><th>সামাজিক ভূমিকা নির্ধারণ</th></tr></thead><tbody><tr><td>প্রথম স্তর</td><td>গান-ইয়ান জিং (এনার্জি উপলব্ধি স্তর)</td><td>প্রাথমিকভাবে মহাবিশ্বের শক্তি এবং আইনের অস্তিত্ব উপলব্ধি করা, আনুষ্ঠানিক সাধনা শুরু করা</td><td>প্রাথমিক অনুভূতি / জীবন উপলব্ধি / স্পেস চেনা</td><td>শিক্ষানবিস</td></tr><tr><td>দ্বিতীয় স্তর</td><td>নিং-ইয়ান জিং (এনার্জি ঘনীভবন স্তর)</td><td>স্থিরভাবে শক্তি শোষণ এবং ঘনীভূত করতে সক্ষম, মৌলিক অভ্যন্তরীণ চক্র স্থাপন করা</td><td>ডিডাকশন / চক্র / স্পেস নিয়ন্ত্রণ</td><td>প্রাথমিক সাধক</td></tr><tr><td>তৃতীয় স্তর</td><td>হুয়া-ইয়ান জিং (এনার্জি রূপান্তর স্তর)</td><td>শক্তি বিশুদ্ধকরণ উচ্চ স্তরে পৌঁছায়, শক্তিকে বিভিন্ন প্রয়োগে রূপান্তর করতে সক্ষম</td><td>পুনরাবৃত্তি / ক্রমাগত জীবন / স্পেস রূপান্তর</td><td>মাঝারি স্তরের সাধক</td></tr><tr><td>চতুর্থ স্তর</td><td>ফা-ইয়ান জিং (আইন এনার্জি স্তর)</td><td>আইন বোঝা এবং নিয়ন্ত্রণ শুরু করা, শক্তি এবং আইন প্রাথমিকভাবে মিশ্রিত হয়</td><td>মিশ্রণ / জীবন রূপান্তর / ফ্যারিসপ্রুডেন্স স্পেস</td><td>উচ্চ স্তরের সাধক</td></tr><tr><td>পঞ্চম স্তর</td><td>দাও-ইয়ান জিং (দাও এনার্জি স্তর)</td><td>কোনো একটি ক্ষেত্রের আইন সম্পর্কে গভীর বোঝাপড়া, ব্যক্তিগত &quot;দাও&quot; গঠন করা</td><td>মূল / মূল জীবন / মূল স্পেস</td><td>মাস্টার স্তরের সাধক</td></tr><tr><td>ষষ্ঠ স্তর</td><td>হে-দাও জিং (দাওের সাথে মিলন স্তর)</td><td>ব্যক্তিগত দাও এবং মহাবিশ্বের মূল আইন গভীরভাবে মিশ্রিত, প্রতিটি কাজই দাওর সাথে মিলে যায়</td><td>একক সিস্টেমের পঞ্চম স্তর অতিক্রম</td><td>গ্র্যান্ডমাস্টার স্তরের সাধক</td></tr><tr><td>সপ্তম স্তর</td><td>পো-জিয়ে জিং (সীমা ভঙ্গ স্তর)</td><td>প্লেন আইনের সীমা অতিক্রম করতে সক্ষম, ক্রস-প্লেন স্থির অপারেশন করতে সক্ষম</td><td>—</td><td>প্লেন-স্তরের শক্তিশালী</td></tr><tr><td>অষ্টম স্তর</td><td>চুয়াং-শি জিং (সৃষ্টি স্তর)</td><td>আইসোলেটেড স্পেসে সম্পূর্ণ বিশ্ব এবং আইন ব্যবস্থা সৃষ্টি করতে সক্ষম</td><td>—</td><td>বিশ্ব-স্তরের শক্তিশালী</td></tr><tr><td>নবম স্তর</td><td>বেন-ইয়ান জিং (মূল স্তর)</td><td>মহাবিশ্বের মূলে স্পর্শ করা, মহাবিশ্বের আইনের সূক্ষ্ম সমন্বয় এবং অপ্টিমাইজেশনে অংশ নিতে সক্ষম</td><td>—</td><td>মহাবিশ্ব-স্তরের শক্তিশালী</td></tr></tbody></table><p>নয়টি স্তরের মধ্যে, প্রথম থেকে পঞ্চম স্তর হলো &quot;পাঁচটি সাধারণ সাধনা স্তর&quot;, যা বেশিরভাগ সাধক প্রচেষ্টার মাধ্যমে পৌঁছাতে পারে; ষষ্ঠ থেকে নবম স্তর হলো &quot;চারটি পবিত্র সাধনা স্তর&quot;, যা পৌঁছাতে অত্যন্ত উচ্চ প্রতিভা, সুযোগ এবং প্রচেষ্টা প্রয়োজন, এবং প্রতিটি স্তরের অতিক্রমই মহাবিশ্ব-স্তরের একটি বড় ঘটনা।</p><h2 id="iii-প্রতিটি-স্তরের-বিস্তারিত-মানদণ্ড" tabindex="-1">III. প্রতিটি স্তরের বিস্তারিত মানদণ্ড <a class="header-anchor" href="#iii-প্রতিটি-স্তরের-বিস্তারিত-মানদণ্ড" aria-label="Permalink to &quot;III. প্রতিটি স্তরের বিস্তারিত মানদণ্ড&quot;">​</a></h2><h3 id="_3-1-প্রথম-স্তর-গান-ইয়ান-জিং-এনার্জি-উপলব্ধি-স্তর" tabindex="-1">3.1 প্রথম স্তর: গান-ইয়ান জিং (এনার্জি উপলব্ধি স্তর) <a class="header-anchor" href="#_3-1-প্রথম-স্তর-গান-ইয়ান-জিং-এনার্জি-উপলব্ধি-স্তর" aria-label="Permalink to &quot;3.1 প্রথম স্তর: গান-ইয়ান জিং (এনার্জি উপলব্ধি স্তর)&quot;">​</a></h3><p>গান-ইয়ান জিং হলো সাধনার সূচনা বিন্দু, এবং এর মূল বিষয় হলো &quot;উপলব্ধি&quot;। গান-ইয়ান জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>মহাবিশ্বে বিচরণকারী শক্তি (লিং-চি, আইনের শক্তি ইত্যাদি)কে স্থিরভাবে উপলব্ধি করতে সক্ষম</li><li>মৌলিক সাধনা পদ্ধতির মাধ্যমে অল্প পরিমাণে শক্তি শরীরে শোষণ করতে সক্ষম</li><li>প্রাথমিক শক্তি উপলব্ধির চেতনা স্থাপন করা, বিভিন্ন ধরনের শক্তি পার্থক্য করতে সক্ষম</li><li>শক্তি দ্রবীভূত হওয়ার কারণে শারীরিক স্বাস্থ্যে প্রাথমিক উন্নতি</li></ul><p>গান-ইয়ান জিংয়ের সাধকরা সমাজে &quot;শিক্ষানবিস&quot; হিসেবে গণ্য হন, এবং তাদের মূল কাজ হলো ভিত্তি তৈরি করা এবং নিজের জন্য উপযুক্ত সাধনা পদ্ধতি খুঁজে বের করা। গান-ইয়ান জিংয়ের অতিক্রমে সাধারণত কয়েক সপ্তাহ থেকে কয়েক মাসের আনুষ্ঠানিক সাধনা প্রয়োজন হয়।</p><h3 id="_3-2-দ্বিতীয়-স্তর-নিং-ইয়ান-জিং-এনার্জি-ঘনীভবন-স্তর" tabindex="-1">3.2 দ্বিতীয় স্তর: নিং-ইয়ান জিং (এনার্জি ঘনীভবন স্তর) <a class="header-anchor" href="#_3-2-দ্বিতীয়-স্তর-নিং-ইয়ান-জিং-এনার্জি-ঘনীভবন-স্তর" aria-label="Permalink to &quot;3.2 দ্বিতীয় স্তর: নিং-ইয়ান জিং (এনার্জি ঘনীভবন স্তর)&quot;">​</a></h3><p>নিং-ইয়ান জিংয়ের মূল বিষয় হলো &quot;ঘনীভবন&quot;। নিং-ইয়ান জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>মহাবিশ্বের শক্তি স্থিরভাবে শোষণ করে শরীরে ব্যবহারযোগ্য শক্তি সঞ্চয় হিসেবে ঘনীভূত করতে সক্ষম</li><li>মৌলিক অভ্যন্তরীণ চক্র ব্যবস্থা স্থাপন করা, শক্তি শরীরে নির্দিষ্ট পথ অনুসরণ করে ঘুরতে পারে</li><li>ঘনীভূত শক্তিকে মৌলিক আক্রমণ-প্রতিরক্ষা বা সহায়ক প্রয়োগে ব্যবহার করতে সক্ষম</li><li>শক্তির বিশুদ্ধতা মৌলিক মানদণ্ডে পৌঁছায়, অতিরিক্ত অমেধ্য ধারণ করে না</li></ul><p>নিং-ইয়ান জিংয়ের সাধকরা ইতিমধ্যেই মৌলিক সাধক পরিচয় অর্জন করেছেন, এবং কিছু নিম্ন-স্তরের সাধনা কাজ এবং সামাজিক সেবায় অংশ নিতে পারেন। নিং-ইয়ান জিংয়ের অতিক্রমে সাধারণত কয়েক মাস থেকে কয়েক বছরের সাধনা প্রয়োজন হয়।</p><h3 id="_3-3-তৃতীয়-স্তর-হুয়া-ইয়ান-জিং-এনার্জি-রূপান্তর-স্তর" tabindex="-1">3.3 তৃতীয় স্তর: হুয়া-ইয়ান জিং (এনার্জি রূপান্তর স্তর) <a class="header-anchor" href="#_3-3-তৃতীয়-স্তর-হুয়া-ইয়ান-জিং-এনার্জি-রূপান্তর-স্তর" aria-label="Permalink to &quot;3.3 তৃতীয় স্তর: হুয়া-ইয়ান জিং (এনার্জি রূপান্তর স্তর)&quot;">​</a></h3><p>হুয়া-ইয়ান জিংয়ের মূল বিষয় হলো &quot;রূপান্তর&quot;। হুয়া-ইয়ান জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>শক্তি বিশুদ্ধকরণ উচ্চ স্তরে পৌঁছায়, এক ধরনের শক্তিকে অন্য ধরনের শক্তিতে রূপান্তর করতে সক্ষম</li><li>শক্তি এবং পদার্থের প্রাথমিক মিথস্ক্রিয়া করতে সক্ষম (যেমন শক্তি বস্তুতে সংযুক্ত করা, শক্তি আকার দেওয়া ইত্যাদি)</li><li>অভ্যন্তরীণ চক্র স্থির এবং দক্ষ, শক্তি পুনরুদ্ধারের গতি ব্যাপকভাবে বৃদ্ধি পায়</li><li>আইনের অস্তিত্ব এবং কার্যকারিতা উপলব্ধি করা শুরু করে</li></ul><p>হুয়া-ইয়ান জিংয়ের সাধকরা সমাজের মেরু শক্তি, এবং মাঝারি স্তরের প্রশিক্ষক, প্রযুক্তিগত কর্মী, প্রাথমিক স্তরের পরিচালক ইত্যাদি পদে কাজ করতে পারেন। হুয়া-ইয়ান জিংয়ের অতিক্রমে সাধারণত কয়েক বছর থেকে এক দশকেরও বেশি সময়ের সাধনা প্রয়োজন হয়।</p><h3 id="_3-4-চতুর্থ-স্তর-ফা-ইয়ান-জিং-আইন-এনার্জি-স্তর" tabindex="-1">3.4 চতুর্থ স্তর: ফা-ইয়ান জিং (আইন এনার্জি স্তর) <a class="header-anchor" href="#_3-4-চতুর্থ-স্তর-ফা-ইয়ান-জিং-আইন-এনার্জি-স্তর" aria-label="Permalink to &quot;3.4 চতুর্থ স্তর: ফা-ইয়ান জিং (আইন এনার্জি স্তর)&quot;">​</a></h3><p>ফা-ইয়ান জিংয়ের মূল বিষয় হলো &quot;আইন&quot;। ফা-ইয়ান জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>কোনো একটি ক্ষেত্রের মৌলিক আইন বোঝা এবং প্রাথমিকভাবে নিয়ন্ত্রণ করতে সক্ষম</li><li>শক্তি এবং আইন প্রাথমিকভাবে মিশ্রিত হয়, &quot;ফা-লি&quot; (আইন শক্তি) নামক উচ্চ-স্তরের শক্তির রূপ তৈরি হয়</li><li>আইনের উপর ভিত্তি করে কৌশল এবং দক্ষতা প্রয়োগ করতে সক্ষম</li><li>চেতনার শক্তি ব্যাপকভাবে বৃদ্ধি পায়, দীর্ঘ সময়ের গভীর ডিডাকশন এবং ধ্যান করতে সক্ষম</li></ul><p>ফা-ইয়ান জিংয়ের সাধকরা সমাজের উচ্চ-স্তরের প্রতিভা, এবং উচ্চ স্তরের প্রশিক্ষক, প্রযুক্তিগত বিশেষজ্ঞ, মাঝারি স্তরের পরিচালক ইত্যাদি পদে কাজ করতে পারেন। ফা-ইয়ান জিংয়ের অতিক্রমে সাধারণত এক দশক থেকে কয়েক দশকের সাধনা প্রয়োজন হয়, এবং এটি অনেক সাধকের জীবনের প্রথম বড় বাধা।</p><h3 id="_3-5-পঞ্চম-স্তর-দাও-ইয়ান-জিং-দাও-এনার্জি-স্তর" tabindex="-1">3.5 পঞ্চম স্তর: দাও-ইয়ান জিং (দাও এনার্জি স্তর) <a class="header-anchor" href="#_3-5-পঞ্চম-স্তর-দাও-ইয়ান-জিং-দাও-এনার্জি-স্তর" aria-label="Permalink to &quot;3.5 পঞ্চম স্তর: দাও-ইয়ান জিং (দাও এনার্জি স্তর)&quot;">​</a></h3><p>দাও-ইয়ান জিংয়ের মূল বিষয় হলো &quot;দাও অর্জন&quot;। দাও-ইয়ান জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>কোনো একটি ক্ষেত্রের আইন সম্পর্কে পদ্ধতিগত এবং গভীর বোঝাপড়া, ব্যক্তিগত অনন্য &quot;দাও&quot; গঠন করা</li><li>ব্যক্তিগত দাও এবং মহাবিশ্বের আইনের সাথে রেজোন্যান্স তৈরি হয়, বৃহত্তর পরিসরের আইনের শক্তি প্রয়োগ করতে সক্ষম</li><li>শক্তি এবং আইন গভীরভাবে মিশ্রিত, প্রতিটি কাজেই আইনের শক্তি অন্তর্ভুক্ত থাকে</li><li>চেতনা উচ্চ স্তরে বিবর্তিত হয়, ক্রস-প্লেন চেতনা উপলব্ধি করতে সক্ষম</li></ul><p>দাও-ইয়ান জিংয়ের সাধকরা সিভিলাইজেশনের &quot;মাস্টার&quot;, এবং নিজেদের ক্ষেত্রে কর্তৃত্বপূর্ণ, সিভিলাইজেশন-স্তরের উপদেষ্টা, গ্র্যান্ড প্রশিক্ষক, উচ্চ স্তরের পরিচালক ইত্যাদি পদে কাজ করতে পারেন। দাও-ইয়ান জিংয়ের অতিক্রমে অত্যন্ত উচ্চ প্রতিভা এবং অন্তর্দৃষ্টি প্রয়োজন, অনেক সাধক জীবনভরে এটি পৌঁছাতে পারে না।</p><h3 id="_3-6-ষষ্ঠ-স্তর-হে-দাও-জিং-দাওের-সাথে-মিলন-স্তর" tabindex="-1">3.6 ষষ্ঠ স্তর: হে-দাও জিং (দাওের সাথে মিলন স্তর) <a class="header-anchor" href="#_3-6-ষষ্ঠ-স্তর-হে-দাও-জিং-দাওের-সাথে-মিলন-স্তর" aria-label="Permalink to &quot;3.6 ষষ্ঠ স্তর: হে-দাও জিং (দাওের সাথে মিলন স্তর)&quot;">​</a></h3><p>হে-দাও জিংয়ের মূল বিষয় হলো &quot;দাওের সাথে মিলন&quot;। হে-দাও জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>ব্যক্তিগত দাও এবং মহাবিশ্বের মূল আইন গভীরভাবে মিশ্রিত, &quot;স্বর্গ ও মানুষের ঐক্য&quot; অবস্থায় পৌঁছায়</li><li>বৃহত্তর পরিসরে আঞ্চলিক আইনের কার্যকারিতা পুনর্লিখন করতে সক্ষম</li><li>জীবনের রূপ উচ্চ মাত্রায় বিবর্তিত হতে শুরু করে, আংশিকভাবে পদার্থিক শরীরের সীমা থেকে মুক্ত হয়</li><li>স্থিতিশীল ব্যক্তিগত অঞ্চল (আইন অঞ্চল) তৈরি করতে সক্ষম</li></ul><p>হে-দাও জিংয়ের সাধকরা সিভিলাইজেশনের &quot;গ্র্যান্ডমাস্টার&quot;, এবং প্রতিটি ক্ষেত্রের শীর্ষস্থানীয় ব্যক্তিত্ব, সিভিলাইজেশনের বিকাশের দিকে গুরুত্বপূর্ণ প্রভাব ফেলেন। হে-দাও জিংয়ের অতিক্রম হলো মহাবিশ্ব-স্তরের একটি ঘটনা, এবং এর জন্য সময়, স্থান এবং মানুষের সমন্বয় প্রয়োজন।</p><h3 id="_3-7-সপ্তম-স্তর-পো-জিয়ে-জিং-সীমা-ভঙ্গ-স্তর" tabindex="-1">3.7 সপ্তম স্তর: পো-জিয়ে জিং (সীমা ভঙ্গ স্তর) <a class="header-anchor" href="#_3-7-সপ্তম-স্তর-পো-জিয়ে-জিং-সীমা-ভঙ্গ-স্তর" aria-label="Permalink to &quot;3.7 সপ্তম স্তর: পো-জিয়ে জিং (সীমা ভঙ্গ স্তর)&quot;">​</a></h3><p>পো-জিয়ে জিংয়ের মূল বিষয় হলো &quot;সীমা ভঙ্গ&quot;। পো-জিয়ে জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>প্লেন আইনের সীমা অতিক্রম করতে সক্ষম, অ্যাঙ্করের সহায়তা ছাড়াই ক্রস-প্লেন ট্রাভার্স করতে সক্ষম</li><li>প্লেনের ঝিল্লির সাথে কাজ করতে সক্ষম, যেমন প্লেন চ্যানেল খোলা, প্লেনের ফাটল মেরামত করা ইত্যাদি</li><li>ব্যক্তিগত অঞ্চল ছোট স্বাধীন স্পেসে প্রসারিত হতে পারে</li><li>জীবনের রূপ আরও উচ্চ-মাত্রিক হয়, বিভিন্ন প্লেনের আইনের পরিবেশে বেঁচে থাকতে সক্ষম</li></ul><p>পো-জিয়ে জিংয়ের শক্তিশালীরা &quot;প্লেন-স্তরের&quot; অস্তিত্ব, এবং স্বাধীনভাবে প্লেন-স্তরের কাজ এবং দায়িত্ব পালন করতে সক্ষম। পো-জিয়ে জিংয়ের অতিক্রম অত্যন্ত কঠিন, এবং সমগ্র হেঙ্গ-ইউয়ান জুতে এই স্তরে পৌঁছানো সাধকের সংখ্যা সীমিত।</p><h3 id="_3-8-অষ্টম-স্তর-চুয়াং-শি-জিং-সৃষ্টি-স্তর" tabindex="-1">3.8 অষ্টম স্তর: চুয়াং-শি জিং (সৃষ্টি স্তর) <a class="header-anchor" href="#_3-8-অষ্টম-স্তর-চুয়াং-শি-জিং-সৃষ্টি-স্তর" aria-label="Permalink to &quot;3.8 অষ্টম স্তর: চুয়াং-শি জিং (সৃষ্টি স্তর)&quot;">​</a></h3><p>চুয়াং-শি জিংয়ের মূল বিষয় হলো &quot;সৃষ্টি&quot;। চুয়াং-শি জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>আইসোলেটেড স্পেসে সম্পূর্ণ বিশ্ব সৃষ্টি করতে সক্ষম, পদার্থ, শক্তি, আইন, জীবন সহ</li><li>নতুন বিশ্বের মৌলিক আইন ব্যবস্থা ডিজাইন এবং প্রণয়ন করতে সক্ষম</li><li>ব্যক্তিগত অঞ্চল সম্পূর্ণ বিশ্বে প্রসারিত হতে পারে</li><li>জীবনের রূপ উচ্চ-মাত্রিক অস্তিত্বের কাছাকাছি, একসাথে একাধিক প্লেনে প্রকাশ পেতে সক্ষম</li></ul><p>চুয়াং-শি জিংয়ের শক্তিশালীরা &quot;বিশ্ব-স্তরের&quot; অস্তিত্ব, এবং তাদের সৃষ্টি করা বিশ্ব সাধনা সম্পদ, পরীক্ষার স্থান, সিভিলাইজেশনের আশ্রয়স্থল ইত্যাদি হিসেবে ব্যবহার করা যেতে পারে। চুয়াং-শি জিংয়ের অতিক্রম হলো মহাবিশ্বের সবচেয়ে বিরল ঘটনাগুলোর মধ্যে একটি।</p><h3 id="_3-9-নবম-স্তর-বেন-ইয়ান-জিং-মূল-স্তর" tabindex="-1">3.9 নবম স্তর: বেন-ইয়ান জিং (মূল স্তর) <a class="header-anchor" href="#_3-9-নবম-স্তর-বেন-ইয়ান-জিং-মূল-স্তর" aria-label="Permalink to &quot;3.9 নবম স্তর: বেন-ইয়ান জিং (মূল স্তর)&quot;">​</a></h3><p>বেন-ইয়ান জিংয়ের মূল বিষয় হলো &quot;মূল&quot;। বেন-ইয়ান জিংয়ে পৌঁছানোর মানদণ্ড অন্তর্ভুক্ত:</p><ul><li>মহাবিশ্বের মূল আইনে স্পর্শ করা, মহাবিশ্বের চূড়ান্ত কার্যকারিতা নিয়ম বোঝতে সক্ষম</li><li>মহাবিশ্বের আইনের সূক্ষ্ম সমন্বয় এবং অপ্টিমাইজেশনে অংশ নিতে সক্ষম, মহাবিশ্বের বিবর্তনের দিকে প্রভাব ফেলতে সক্ষম</li><li>জীবনের রূপ মহাবিশ্বের মূলের সাথে গভীর সংযোগ তৈরি করে, প্রায় অমর হয়</li><li>মহাবিশ্বের স্কেলে মূল শক্তি প্রয়োগ করতে সক্ষম</li></ul><p>বেন-ইয়ান জিংয়ের শক্তিশালীরা &quot;মহাবিশ্ব-স্তরের&quot; অস্তিত্ব, এবং হেঙ্গ-ইউয়ান জুতে সবচেয়ে শীর্ষস্থানীয় শক্তি। বেন-ইয়ান জিংয়ে পৌঁছানো সাধকদের সাধারণত &quot;প্লেনের সর্বোচ্চ শক্তিশালী&quot; বলা হয়, এবং তারা সিম্বায়োটিক সিভিলাইজেশনের &quot;20% অ্যাক্টিভেশন কৌশল&quot;ের মূল লক্ষ্য গোষ্ঠী।</p><h2 id="iv-স্তর-সার্টিফিকেশন-প্রক্রিয়া" tabindex="-1">IV. স্তর সার্টিফিকেশন প্রক্রিয়া <a class="header-anchor" href="#iv-স্তর-সার্টিফিকেশন-প্রক্রিয়া" aria-label="Permalink to &quot;IV. স্তর সার্টিফিকেশন প্রক্রিয়া&quot;">​</a></h2><p>স্তর মূল্যায়নের ন্যায়বিচার এবং নির্ভুলতা নিশ্চিত করার জন্য, সিম্বায়োটিক সিভিলাইজেশন কঠোর স্তর সার্টিফিকেশন প্রক্রিয়া প্রতিষ্ঠা করেছে:</p><ol><li><strong>অ্যাঙ্কর স্বয়ংক্রিয় পর্যবেক্ষণ</strong>: সাধক অ্যাঙ্কর নেটওয়ার্কের সাথে সংযুক্ত হওয়ার পর, অ্যাঙ্কর তার শক্তির স্তর, আইনের বোঝাপড়া, চেতনার শক্তি ইত্যাদি সূচক ক্রমাগত পর্যবেক্ষণ করবে, এবং যখন সূচকগুলো নতুন স্তরের মানদণ্ডে পৌঁছাবে তখন স্বয়ংক্রিয়ভাবে পরামর্শ দেবে</li><li><strong>মানদণ্ড কমিটির পরীক্ষা</strong>: চতুর্থ স্তর এবং তার উপরের স্তরের অতিক্রমের জন্য, সাধনা মানদণ্ড কমিটির দ্বারা আনুষ্ঠানিক পরীক্ষা আয়োজন করতে হবে, পরীক্ষার বিষয়বস্তুতে তাত্ত্বিক পরীক্ষা, বাস্তব পরীক্ষা, এবং অবদান মূল্যায়ন — এই তিনটি দিক অন্তর্ভুক্ত</li><li><strong>প্রকাশ এবং আপত্তি সময়কাল</strong>: পরীক্ষা পাস করার পর ত্রিশ দিনের জন্য প্রকাশ করা হবে, প্রকাশের সময়কালে যেকোনো জীবন আপত্তি তুলতে পারে, এবং আপত্তি প্রমাণিত হলে পুনরায় পরীক্ষা করতে হবে</li><li><strong>স্তর সনদ প্রদান</strong>: প্রকাশে কোনো আপত্তি না থাকলে, অ্যাঙ্কর নেটওয়ার্ক দ্বারা ঐক্যকৃত স্তর সনদ প্রদান করা হবে, এবং সনদের তথ্য সিভিলাইজেশন ডেটাবেসে录入 করা হবে</li></ol><h2 id="v-স্তর-এবং-সামাজিক-অধিকার-দায়িত্বের-প্রতিসাম্য" tabindex="-1">V. স্তর এবং সামাজিক অধিকার-দায়িত্বের প্রতিসাম্য <a class="header-anchor" href="#v-স্তর-এবং-সামাজিক-অধিকার-দায়িত্বের-প্রতিসাম্য" aria-label="Permalink to &quot;V. স্তর এবং সামাজিক অধিকার-দায়িত্বের প্রতিসাম্য&quot;">​</a></h2><p>বিভিন্ন স্তরের সাধকরা সিম্বায়োটিক সিভিলাইজেশনে বিভিন্ন অধিকার উপভোগ করে এবং বিভিন্ন দায়িত্ব পালন করে:</p><table tabindex="0"><thead><tr><th>স্তর</th><th>মূল অধিকার</th><th>মূল দায়িত্ব</th></tr></thead><tbody><tr><td>গান-ইয়ান - নিং-ইয়ান জিং</td><td>বিনামূল্যে মৌলিক সাধনা সম্পদ প্রাপ্তি, পাবলিক সাধনা স্থানের ব্যবহার অধিকার</td><td>সাধনা নৈতিকতা পালন, মৌলিক সম্প্রদায় সেবায় অংশ নেওয়া</td></tr><tr><td>হুয়া-ইয়ান - ফা-ইয়ান জিং</td><td>উন্নত সম্পদ বণ্টন অধিকার, প্রশিক্ষক যোগ্যতা আবেদন অধিকার, ক্রস-অঞ্চল চলাচল অধিকার</td><td>প্রাথমিক সাধকদের প্রশিক্ষণ দেওয়া, প্রযুক্তিগত গবেষণা বা সামাজিক সেবায় অংশ নেওয়া</td></tr><tr><td>দাও-ইয়ান - হে-দাও জিং</td><td>উচ্চ-স্তরের সম্পদ বণ্টন অধিকার, অ্যাঙ্কর উচ্চ-স্তরের প্রবেশ অধিকার, সিভিলাইজেশন সিদ্ধান্তে অংশ নেওয়ার অধিকার</td><td>সিভিলাইজেশন-স্তরের গবেষণা প্রকল্পের দায়িত্ব পালন, আঞ্চলিক অ্যাঙ্করের স্থায়িত্ব রক্ষা করা</td></tr><tr><td>পো-জিয়ে - চুয়াং-শি জিং</td><td>প্লেন-স্তরের সম্পদ বিন্যাস অধিকার, স্বাধীন স্পেস তৈরির অধিকার, প্লেন বিষয়ক কাজে অংশ নেওয়ার অধিকার</td><td>প্লেন-স্তরের কাজের দায়িত্ব পালন, প্লেনের ঝিল্লির স্থায়িত্ব রক্ষা করা, ক্রস-প্লেন বিষয়ক কাজে অংশ নেওয়া</td></tr><tr><td>বেন-ইয়ান জিং</td><td>মহাবিশ্ব-স্তরের সম্পদ বিন্যাস অধিকার, আইনের সূক্ষ্ম সমন্বয়ে অংশ নেওয়ার অধিকার, সিভিলাইজেশনের সর্বোচ্চ সিদ্ধান্তে অংশ নেওয়ার অধিকার</td><td>মহাবিশ্বের সামগ্রিক স্থায়িত্ব রক্ষা করা, সিভিলাইজেশনের বিবর্তনের দিক নির্দেশনা দেওয়া, উত্তরসূরি প্রতিভা প্রশিক্ষণ দেওয়া</td></tr></tbody></table><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সাধনা স্তরের ঐক্যকৃত বিভাজন মানদণ্ড হলো অ্যাঙ্কর সিম্বায়োটিক সিভিলাইজেশনের সাধনা ব্যবস্থার অন্যতম মৌলিক অবকাঠামো। এটি তিনশট সাধনা পদ্ধতির জন্য একটি সাধারণ &quot;মাপকাঠি&quot; প্রদান করে, যা ক্রস-সিস্টেম যোগাযোগ, সহযোগিতা, প্রতিযোগিতাকে সম্ভব করে তোলে, এবং সম্পদ বণ্টন, সামাজিক শাসন, প্রতিভা প্রশিক্ষণের জন্যও বস্তুনিষ্ঠ ভিত্তি প্রদান করে। নয়টি স্তরের বিভাজন শ্রেণিগত পার্থক্য তৈরি করার জন্য নয়, বরং প্রতিটি সাধকের বিবর্তনের পর্যায়কে স্পষ্টভাবে চিহ্নিত করার জন্য, এবং তাদের জন্য সবচেয়ে উপযুক্ত সহায়তা এবং নির্দেশনা প্রদান করার জন্য। স্তরের উন্নতি শেষ প্রান্ত নয়, বরং উচ্চ স্তরের সিম্বায়োটিক বিবর্তনের দিকে একটি নতুন সূচনা বিন্দু।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (তিনশট মূল সাধনা পদ্ধতির সারসংক্ষেপ)</li><li>17-位面至高强者标准 (প্লেনের সর্বোচ্চ শক্তিশালীর মানদণ্ড)</li><li>29-共生度评估体系 (সিম্বায়োসিস মাত্রা মূল্যায়ন ব্যবস্থা)</li></ul>',57)])])}const b=d(o,[["render",r]]);export{s as __pageData,b as default};
